// One item: every job ID already in the Sheet (incl. aliases from other job boards), so a job is scored once.
const seen = [];
for (const { json: r } of $input.all()) {
  for (const v of [r.job_id, ...String(r.job_id_aliases || '').split(',')]) {
    const id = String(v || '').trim();
    if (id) seen.push(id);
  }
}
return [{ json: { seen } }];

// Your CV as plain text: from the Google Doc if cvDocUrl is set, otherwise from Settings → cvText (the only two ways to provide it).
// Stops here (before any Apify cost) if there is no CV yet.
const s = $('Settings').first().json;
let cv = String(s.cvText || '');
if (String(s.cvDocUrl || '').trim()) {
  // The Docs node ships deactivated (a workflow can only be activated when every active node has its credential). A deactivated node passes its input through unchanged: no `content`.
  const doc = $('Read CV from Google Docs').first().json;
  if (!('content' in doc)) throw new Error("cvDocUrl is set: activate the node 'Read CV from Google Docs' (right-click > Activate) and connect Google Docs. Or empty cvDocUrl and paste your CV into cvText.");
  cv = String(doc.content || '');
}
cv = cv.trim();
if (!cv || cv.startsWith('PASTE YOUR CV')) throw new Error('No CV yet. Open the Settings node and either paste your CV as plain text into cvText (open your CV, select all, copy, paste), or put the link of a Google Doc that contains your CV into cvDocUrl. Then run again.');
return [{ json: { cv: cv.slice(0, 12000), seen: $('Known job IDs').first().json.seen } }];

// Drop jobs already in the Sheet (by job_id and its aliases), duplicates and rows without a title.
// Builds the scoring prompt for each new job.
const s = $('Settings').first().json;
const { cv, seen } = $('CV ready').first().json;
const known = new Set(seen);
// Only rows that came from a "Company websites" entry (companyUrls) tell you something new: the career page job-feed detected.
const fromCompanyUrl = j => (j.input_refs || []).some(r => r && r.source === 'companyUrls');
const language = String(s.language || '').trim() || 'English';
// Contact columns: only what job-feed emitted (the job ad's contacts[] and the company.* fields). Blank when absent, never guessed.
// A text starting with = + - @ gets a leading apostrophe so Google Sheets keeps it as text (phone numbers like +41 ...).
const safe = v => { v = String(v == null ? '' : v).trim(); return /^[=+\-@]/.test(v) ? "'" + v : v; };
const uniq = a => [...new Set(a.map(x => String(x || '').trim()).filter(Boolean))];
// company_website comes ONLY from job-feed's company fields (website, url, domain), never from the career page, the job system or the careerSites input.
// A value that is that kind of address (same as ats_url / career_page_url / an input_refs url, or a known job-system host) is dropped: blank beats a wrong site.
const ATS_HOST = /(^|\.)(greenhouse\.io|lever\.co|ashbyhq\.com|myworkdayjobs\.com|workday\.com|personio\.(de|com)|smartrecruiters\.com|workable\.com|recruitee\.com|teamtailor\.com|jobvite\.com|bamboohr\.com|icims\.com|breezy\.hr|join\.com|softgarden\.io|successfactors\.(com|eu)|taleo\.net|eightfold\.ai|dayforcehcm\.com|rippling\.com|gohire\.io)$/i;
const hostOf = u => String(u || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split(/[/?#]/)[0];
const normU = u => String(u || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/+$/, '');
const ownSite = (j, co) => {
  const boards = new Set([j.ats_url, j.career_page_url, ...(j.input_refs || []).map(r => r && r.url)].map(normU).filter(Boolean));
  for (const c of [co.website, co.url, co.domain]) {
    const v = String(c || '').trim();
    if (!v || boards.has(normU(v)) || ATS_HOST.test(hostOf(v))) continue;
    return /^https?:\/\//i.test(v) ? v : 'https://' + v;
  }
  return '';
};
const contactFields = j => {
  const cs = Array.isArray(j.contacts) ? j.contacts : [];
  const c0 = cs[0] || {};
  const co = j.company || {};
  const soc = (co.social_urls && typeof co.social_urls === 'object') ? co.social_urls : {};
  const linkedinKey = Object.keys(soc).find(k => /linkedin/i.test(k));
  const others = Object.entries(soc).filter(([k, v]) => v && k !== linkedinKey).map(([k, v]) => k + ': ' + (Array.isArray(v) ? v[0] : v));
  return {
    contact_name: safe([c0.first_name, c0.last_name].filter(Boolean).join(' ')),
    contact_email: safe(uniq(cs.map(c => c && c.email)).join(', ')),
    contact_phone: safe(uniq(cs.map(c => c && c.phone)).join(', ')),
    contact_position: safe(c0.position),
    company_website: safe(ownSite(j, co)),
    company_email: safe(co.email),
    company_phone: safe(co.phone),
    company_linkedin: safe(linkedinKey ? (Array.isArray(soc[linkedinKey]) ? soc[linkedinKey][0] : soc[linkedinKey]) : ''),
    company_social_urls: safe(others.join(', ')),
  };
};
// Second dedupe key: the apply URL (lower case, no protocol/www/fragment, no trailing slash, no trailing /apply or /application; the query string stays minus tracking parameters like utm_*, inv, ref, lang, sorted).
// The same job read through a website and through its career page gets different job IDs but the same URL. Stored in job_id_aliases as "url:<key>".
const TRACK = /^(utm_.*|mc_.*|source|src|ref|referrer|inv|trk|trackingid|refid|gclid|fbclid|campaign|medium|showapplicationform|dialog|locale|lang)$/;
const urlKey = u => {
  const [pathAndQuery] = String(u || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('#');
  const [path0, ...qs] = pathAndQuery.split('?');
  const path = path0.replace(/\/+$/, '').replace(/\/(apply|application)$/, '').replace(/\/+$/, '');
  // The query string stays (job boards identify the job with ?id=...), minus tracking parameters, sorted.
  const q = qs.join('?').split('&').filter(Boolean).filter(x => !TRACK.test(x.split('=')[0])).sort().join('&');
  return path.includes('/') ? 'url:' + path + (q ? '?' + q : '') : '';
};
const out = [];
for (const { json: j } of $input.all()) {
  if (!j.job_id || !j.title) continue;
  const uk = urlKey(j.apply_url);
  const ids = [j.job_id, ...(j.job_id_aliases || []), ...(uk ? [uk] : [])].map(String);
  if (ids.some(id => known.has(id))) continue;
  ids.forEach(id => known.add(id));
  const company = (j.company && j.company.name) || '';
  const loc = j.location || {};
  const description = String(j.description_text || '').trim();
  const job = {
    job_id: String(j.job_id),
    job_id_aliases: [...(j.job_id_aliases || []), ...(uk ? [uk] : [])].join(', '),
    found_at: $now.toFormat('yyyy-LL-dd HH:mm'),
    title: j.title,
    company,
    location: [loc.city, loc.country].filter(Boolean).join(', '),
    remote: loc.remote ? 'yes' : '',
    posted_date: String(j.posted_date || '').slice(0, 10),
    platform: j._platform || '',
    apply_url: j.apply_url || '',
    detected_career_page: fromCompanyUrl(j) ? String(j.ats_url || j.career_page_url || '') : '',
    hasDescription: description.length > 0,
    ...contactFields(j),
    gmail_draft: '',
  };
  job.scorePrompt = `You compare one job ad with one CV. Reply with JSON only, no other text: {"score": <0-100>, "reason": "<two short lines>"}.
Score how well the CV matches the job's must-have requirements (skills, experience, languages, location). 90+ = strong match, 70 = worth applying, below 50 = poor fit. Do not invent experience the CV does not show.
${description ? '' : 'The job description is missing: score from the title and company only and say so in the reason.'}
The CV and the job ad can be in any language. Write the reason in ${language}.

CV:
${cv}

Job: ${job.title} at ${company || 'unknown company'}, ${job.location || 'location not given'}
Description:
${description ? description.slice(0, 6000) : '(none)'}`;
  job.description = description.slice(0, 6000);
  out.push({ json: job });
  if (out.length >= s.maxJobsPerRun) break;
}
// No new jobs: one marker item, so the run is still marked collected (the IF after this node sends it past the AI steps).
return out.length ? out : [{ json: { noNewJobs: true } }];

// Read the model's JSON. If it can't be parsed, score 0 and keep the raw answer in the reason.
const job = $('Keep unseen jobs').item.json;
const s = $('Settings').first().json;
const raw = String($json.text || $json.output || '');
let score = 0, reason = raw.slice(0, 300);
try {
  const m = raw.match(/\{[\s\S]*\}/);
  const r = JSON.parse(m ? m[0] : raw);
  score = Math.max(0, Math.min(100, Math.round(Number(r.score) || 0)));
  reason = String(r.reason || '').trim();
} catch (e) {}
const language = String(s.language || '').trim() || 'English';
const words = String(s.letterWords || '').trim() || '180-250';
const style = String(s.letterStyle || '').trim();
const cv = $('CV ready').first().json.cv;
const letterPrompt = `Write a cover letter draft in ${language} for this job. The whole letter is in ${language}, even if the CV or the job ad is in another language. ${words} words. Use only facts from the CV: do not claim any skill, employer, degree, number or experience that is not in the CV, even if the job asks for it. Don't make a skill bigger than the CV states ("REST APIs" does not become "API design"). Where a short fact is missing (a date, an amount, a name), put it in square brackets, written in ${language}, inside a natural, complete sentence, for example "I could start on [start date].", [salary expectation] or [contact person] (translate these examples into ${language}). Never put a whole claim or commitment in brackets (availability, willingness to relocate, skills): leave it out instead. At most 3 bracketed items. Never write the word "placeholder" or its translation in ${language}. No address block, no date, no subject line. Close with the usual polite closing phrase in ${language}, followed by ${s.yourName}. Reply with the letter text only.${style ? `
Style: ${style}` : ''}

CV:
${cv}

Job: ${job.title} at ${job.company}, ${job.location}
Job description:
${job.description}`;
return { json: { ...job, score, reason, letterPrompt } };

// Attach the drafted letter to its job. The status is only ever written here, once, when the row is created.
const j = $('Worth a letter?').item.json;
const letter = String($json.text || $json.output || '').trim();
return { json: { ...j, letter, note: letter ? '' : 'the AI returned no letter', status: letter ? 'Letter drafted' : 'To review' } };

// Below the minimum score or no job description: no letter is drafted. The reason goes to the note column.
const j = $json;
const note = !j.hasDescription ? 'no description, letter not drafted' : `score below ${$('Settings').first().json.minScore}, letter not drafted`;
return { json: { ...j, letter: '', note, status: 'To review' } };

// Reads the three input tabs and builds the job-feed input(s). A row with active = no is skipped; empty tabs are fine.
const s = $('Settings').first().json;
// Every input cell is cleaned first: tabs, line breaks and runs of spaces become ONE space, then trimmed. In keywords and country a line break still separates entries.
const clean = v => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
const cleanRow = r => Object.fromEntries(Object.entries(r).map(([k, v]) => [k, typeof v !== 'string' ? v : /^(keywords|country)$/.test(k) ? v.split(/\r?\n/).map(clean).filter(Boolean).join(', ') : clean(v)]));
const on = r => !/^\s*(no|n|false|0|off|nein)\s*$/i.test(String(r.active == null ? '' : r.active));
const rows = name => $(name).all().map(i => cleanRow(i.json)).filter(on);
const list = v => String(v == null ? '' : v).split(/[,;\n]/).map(x => x.trim()).filter(Boolean);
const full = u => (u = String(u || '').trim()) && (/^https?:\/\//i.test(u) ? u : 'https://' + u);
const bool = (v, d) => v == null || v === '' ? d : !/^\s*(false|no|0|off|nein)\s*$/i.test(String(v));
const common = { postedWithinDays: Number(s.postedWithinDays) || 0, onlyNewJobs: true, includeJobDetails: true, maxResultsTotal: Number(s.maxJobsPerRun) || 50,
  includeContactData: bool(s.includeContactData, true), includeCompanyDetails: bool(s.includeCompanyDetails, false) };
const openRuns = () => $('Read Runs tab').all().map(i => i.json)
  .filter(r => /^(RUNNING|READY)$/i.test(String(r.status || '').trim()) && String(r.run_url || '').trim())
  .map(r => ({ id: String(r.run_url).trim().replace(/\/+$/, '').split('/').pop(), run_url: String(r.run_url).trim(), search: String(r.search || ''), mode: String(r.mode || ''), status: String(r.status).trim().toUpperCase() }));
// Set when this execution was started by the "Apify run finished" webhook: only that run is collected, and nothing new is started.
let hookRun = '';
try { hookRun = String($('Apify run finished').first().json.body.runId || ''); } catch (e) {}
const out = [];

// 1. Job boards & keywords: rows with the same country, location, radius and platform share one search (one job-feed run).
const groups = new Map();
rows('Read keyword rows').forEach((r, n) => {
  const keywords = list(r.keywords);
  if (!keywords.length) return;
  const platform = String(r.platform || '').trim().toLowerCase();
  const countries = list(r.country).map(c => c.toUpperCase());
  if (!platform && !countries.length) throw new Error(`Row ${n + 2} of the tab "Job boards & keywords" needs a country (for example CH, DE or GB) or a platform (for example linkedin).`);
  const location = String(r.location || '').trim();
  const radiusKm = Number(r.radiusKm) > 0 ? Number(r.radiusKm) : 0;
  const key = [platform ? '' : countries.join('+'), platform, location, radiusKm].join('|');
  if (!groups.has(key)) groups.set(key, { platform, countries, location, radiusKm, keywords: [] });
  keywords.forEach(k => { if (!groups.get(key).keywords.includes(k)) groups.get(key).keywords.push(k); });
});
for (const g of groups.values()) {
  out.push({ mode: 'boards', search: [g.platform || g.countries.join('+'), g.keywords.join(', '), g.location].filter(Boolean).join(' / '),
    body: { ...common, excludeAgencies: true, keywords: g.keywords,
    ...(g.platform ? { platforms: [g.platform] } : { countries: g.countries }),
    ...(g.location ? { location: g.location } : {}), ...(g.radiusKm ? { radiusKm: g.radiusKm } : {}) } });
}

// 2. Company websites (job-feed finds the career page) and 3. Career pages (job system known, cheaper).
// The optional keywords column of each row filters that company's jobs (blank = all its jobs, still capped). job-feed's keywords are global per run,
// so rows with the same keyword set share one run; the board keywords above are NOT used here.
const normSite = u => String(u || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/+$/, '');
// A website that already has an ACTIVE Career pages row (found_from_website) is read through that career page instead: cheaper and faster.
// Set that career row to active = no and the website is used again.
const handed = new Set(rows('Read career pages').map(r => normSite(r.found_from_website)).filter(Boolean));
const seen = new Set();
const compGroups = new Map();
// One run per mode (websites / career pages) and keyword set: job-feed's maxResultsTotal fills in arrival order, so mixing modes (or many companies under a small cap) would starve some companies.
const compGroup = (kind, kws) => { const k = kind + '#' + kws.map(x => x.toLowerCase()).sort().join('|'); if (!compGroups.has(k)) compGroups.set(k, { keywords: kws, companyUrls: [], careerSites: [] }); return compGroups.get(k); };
rows('Read company websites').forEach(r => { const u = full(r.website); if (u && !handed.has(normSite(u)) && !seen.has(u.toLowerCase())) { seen.add(u.toLowerCase()); compGroup('w', list(r.keywords)).companyUrls.push(u); } });
rows('Read career pages').forEach(r => { const u = full(r.career_page_url); if (u && !seen.has(u.toLowerCase())) { seen.add(u.toLowerCase()); const company = String(r.company || '').trim(); compGroup('c', list(r.keywords)).careerSites.push(company ? { url: u, company } : { url: u }); } });
for (const g of compGroups.values()) {
  const host = u => String(u).replace(/^https?:\/\//, '').replace(/^www\./, '').split(/[/?#]/)[0];
  const names = [...g.companyUrls.map(host), ...g.careerSites.map(c => c.company || host(c.url))];
  out.push({ mode: g.companyUrls.length ? 'websites' : 'career pages',
    search: names.slice(0, 5).join(', ') + (names.length > 5 ? ' (+' + (names.length - 5) + ')' : '') + (g.keywords.length ? ' | ' + g.keywords.join(', ') : ''),
    // Each company gets up to maxJobsPerCompany; the run total is exactly that times the number of companies, so the total cap never starves a company.
    body: { ...common, maxResultsPerCompany: Number(s.maxJobsPerCompany) || 20, maxResultsTotal: (Number(s.maxJobsPerCompany) || 20) * (g.companyUrls.length + g.careerSites.length),
    ...(g.keywords.length ? { keywords: g.keywords } : {}),
    ...(g.companyUrls.length ? { companyUrls: g.companyUrls } : {}), ...(g.careerSites.length ? { careerSites: g.careerSites } : {}) } });
}
// Nothing is started here. A search whose previous run is still RUNNING (Runs tab) is skipped. A webhook execution only collects.
const busy = new Set(openRuns().map(r => r.mode + '|' + r.search));
return [{ json: { starts: hookRun ? [] : out.filter(x => !busy.has(x.mode + '|' + x.search)) } }];

// One Apify run per search. The start query is built here (timeout, memory, cost cap, optional ad-hoc webhook).
const s = $('Settings').first().json;
const hook = String(s.webhookUrl || '').trim();
const b64 = t => typeof Buffer !== 'undefined' ? Buffer.from(t, 'utf8').toString('base64') : btoa(unescape(encodeURIComponent(t)));
const query = { waitForFinish: 0, timeout: Math.round((Number(s.apifyRunTimeoutMinutes) || 240) * 60), memory: 1024, maxTotalChargeUsd: Number(s.maxCostPerRunUsd) || 0.5 };
if (hook) query.webhooks = b64(JSON.stringify([{ eventTypes: ['ACTOR.RUN.SUCCEEDED', 'ACTOR.RUN.FAILED', 'ACTOR.RUN.ABORTED', 'ACTOR.RUN.TIMED_OUT'],
  requestUrl: hook, payloadTemplate: '{"runId": {{resource.id}}, "status": {{resource.status}}}' }]));
return $input.first().json.starts.map(x => ({ json: { ...x, query } }));

// One Runs-tab row per started run. A run that could not be started is logged too (status FAILED, with the reason).
const src = $('One item per job-feed search').all();
const now = $now.toFormat('yyyy-LL-dd HH:mm');
return $input.all().map((it, i) => {
  const r = (it.json && it.json.data) || it.json || {}, s = (src[i] || { json: {} }).json;
  const e0 = (it.json && it.json.error) || r.error;
  const err = e0 ? String((e0 && (e0.message || e0.description)) || e0) : (r.id ? '' : String(r.message || 'no run ID returned'));
  return { json: { started_at: now, search: s.search || '', mode: s.mode || '', status: r.id ? 'RUNNING' : 'FAILED', jobs: '', charged_usd: '',
    run_url: r.id ? 'https://console.apify.com/view/runs/' + r.id : '', collected_at: r.id ? '' : now, note: r.id ? '' : 'could not start: ' + err, run_id: r.id || '' } };
});

// Everything to poll: the runs started just now plus the runs of earlier executions that are still RUNNING (for this part of the workflow).
const openRuns = () => $('Read Runs tab').all().map(i => i.json)
  .filter(r => /^(RUNNING|READY)$/i.test(String(r.status || '').trim()) && String(r.run_url || '').trim())
  .map(r => ({ id: String(r.run_url).trim().replace(/\/+$/, '').split('/').pop(), run_url: String(r.run_url).trim(), search: String(r.search || ''), mode: String(r.mode || ''), status: String(r.status).trim().toUpperCase() }));
const mine = ['boards', 'websites', 'career pages', 'websites + career pages'];
const hook = String($('Settings').first().json.webhookUrl || '').trim();
let hookRun = '';
try { hookRun = String($('Apify run finished').first().json.body.runId || ''); } catch (e) {}
let fresh = [];
// With a webhook URL set, new runs are not watched here: Apify calls the webhook when they finish.
if (!hook) try { fresh = $('Log the new job-feed runs').all().map(i => i.json).filter(r => r.run_id).map(r => ({ id: r.run_id, run_url: r.run_url, search: r.search, mode: r.mode, status: 'RUNNING' })); } catch (e) {}
const seen = new Set();
const out = [];
for (const r of [...fresh, ...openRuns().filter(r => mine.includes(r.mode) && (!hookRun || r.id === hookRun))]) { if (!r.id || seen.has(r.id)) continue; seen.add(r.id); out.push({ json: r }); }
return out;

// Sort the runs by outcome. Keeps looping while a run is still open and Settings.maxWaitMinutes is not used up.
const s = $('Settings').first().json;
const maxPolls = String(s.webhookUrl || '').trim() ? 0 : Math.floor((Number(s.maxWaitMinutes) >= 0 ? Number(s.maxWaitMinutes) : 30) * 60 / 70);
const polls = $runIndex + 1;
const base = $('Runs to watch (job-feed)').all().map(i => i.json);
const got = $input.all().map(i => i.json || {});
// What the run charges you: pay-per-event actors = sum(chargedEventCounts x event price) (+ platform usage only when the run bills usage to the user); other runs = usageTotalUsd.
const chargedOf = r => {
  const ev = (((r.pricingInfo || {}).pricingPerEvent || {}).actorChargeEvents) || null;
  if (!ev || !/PAY_PER_EVENT/i.test(String((r.pricingInfo || {}).pricingModel || ''))) return r.usageTotalUsd;
  const cnt = r.chargedEventCounts || {};
  let t = 0;
  for (const k of Object.keys(cnt)) t += (Number(cnt[k]) || 0) * (Number((ev[k] || {}).eventPriceUsd) || 0);
  if (String(r.platformUsageBillingModel || '').toUpperCase() === 'USER') t += Number(r.usageTotalUsd) || 0;
  return t;
};
const isOpen = st => ['READY', 'RUNNING', 'TIMING-OUT', 'ABORTING'].includes(st);
const rows = base.map((b, i) => { const r = got[i] || {}; return { ...b, status: String(r.status || (r.error ? 'UNKNOWN' : b.status || 'UNKNOWN')).toUpperCase(), defaultDatasetId: r.defaultDatasetId || '',
  charged: chargedOf(r), jobs: (r.chargedEventCounts || {})['orchestrator-unique-job'], note: r.error ? 'could not read the run status: ' + String((r.error && r.error.message) || r.error) : '' }; });
const stillRunning = rows.some(r => isOpen(r.status)) && polls <= maxPolls;
return rows.map(r => ({ json: { ...r, stillRunning, polls, outcome: r.status === 'SUCCEEDED' ? 'done' : isOpen(r.status) ? 'running' : 'problem' } }));

// Runs of this execution whose dataset was just processed: mark them collected, so they are never processed twice.
const fmt = u => (u == null || u === '' || isNaN(Number(u))) ? '' : String(Math.round(Number(u) * 10000) / 10000);
const now = $now.toFormat('yyyy-LL-dd HH:mm');
return $('Check the job-feed runs').all().map(i => i.json).filter(r => r.outcome === 'done' && !r.stillRunning)
  .map(r => ({ json: { run_url: r.run_url, status: 'SUCCEEDED', jobs: r.jobs == null ? '' : r.jobs, charged_usd: fmt(r.charged), collected_at: now, note: '' } }));

const fmt = u => (u == null || u === '' || isNaN(Number(u))) ? '' : String(Math.round(Number(u) * 10000) / 10000);
const r = $json;
const now = $now.toFormat('yyyy-LL-dd HH:mm');
const note = r.status === 'UNKNOWN' ? (r.note || 'could not read the run status (deleted or expired?)') : 'The run ended with status ' + r.status + '. Open run_url to see why. Nothing was collected from it.';
return { json: { run_url: r.run_url, status: r.status, jobs: '', charged_usd: fmt(r.charged), collected_at: now, note } };

// Hand-over from "Company websites" to "Career pages": when job-feed found the job system of a company you gave as a website,
// add that career page to the Career pages tab (once per company), so the next runs read it directly: cheaper and faster.
// A job is matched to its website through input_refs (source companyUrls, url = the website exactly as this workflow sent it).
const normSite = u => String(u || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/+$/, '');
const normPage = u => String(u || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/\/+$/, '');
const on = r => !/^\s*(no|n|false|0|off|nein)\s*$/i.test(String(r.active == null ? '' : r.active));
// Every input cell is cleaned first: tabs, line breaks and runs of spaces become ONE space, then trimmed. In keywords and country a line break still separates entries.
const clean = v => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
const cleanRow = r => Object.fromEntries(Object.entries(r).map(([k, v]) => [k, typeof v !== 'string' ? v : /^(keywords|country)$/.test(k) ? v.split(/\r?\n/).map(clean).filter(Boolean).join(', ') : clean(v)]));
const known = new Set($('Read career pages').all().map(i => normPage(cleanRow(i.json).career_page_url)).filter(Boolean));
const keywordsOf = new Map($('Read company websites').all().map(i => cleanRow(i.json)).filter(r => String(r.website || '').trim() && on(r)).map(r => [normSite(r.website), String(r.keywords || '').trim()]));
const out = [];
for (const { json: j } of $('Get job-feed results').all()) {
  const ref = (j.input_refs || []).find(r => r && r.source === 'companyUrls' && r.url);
  const page = String(j.ats_url || j.career_page_url || '').trim();
  if (!ref || !page || known.has(normPage(page))) continue;
  known.add(normPage(page));
  const site = normSite(ref.url);
  out.push({ json: { career_page_url: page, company: (j.company && j.company.name) || '', keywords: keywordsOf.get(site) || '', active: 'yes', found_from_website: site } });
}
return out.length ? out : [{ json: { none: true } }];

// createGmailDrafts is on: for every job with a drafted letter, pick the address (contact first, else the company's) and build the draft.
// Nothing is sent: the next node only creates a Gmail DRAFT. At most maxDraftsPerRun drafts per run.
const s = $('Settings').first().json;
const cap = Number(s.maxDraftsPerRun) >= 0 ? Number(s.maxDraftsPerRun) : 10;
const tpl = String(s.draftSubject || 'Application: {title}');
const first = v => String(v || '').split(',')[0].trim().replace(/^'/, '');
let n = 0;
return $input.all().map(({ json: j }) => {
  const to = first(j.contact_email) || first(j.company_email);
  if (!to) return { json: { ...j, gmail_draft: 'no email', draft_ok: false } };
  if (n >= cap) return { json: { ...j, gmail_draft: 'limit reached', draft_ok: false } };
  n++;
  return { json: { ...j, draft_ok: true, draft_to: to, draft_subject: tpl.replace(/\{title\}/g, j.title || '').replace(/\{company\}/g, j.company || ''), draft_body: j.letter } };
});

// The Gmail node created the draft (or reported an error). Put the outcome back on the job row.
const j = $('Prepare the Gmail drafts').item.json;
// The Gmail node ships deactivated; a deactivated node passes its input through unchanged (no draft id), so that is not reported as a draft.
const failed = $json && $json.error;
const made = $json && !failed && ($json.id || ((($json.message || {}).labelIds) || []).includes('DRAFT'));
return { json: { ...j, gmail_draft: failed ? ('draft failed: ' + String((failed && failed.message) || failed).slice(0, 120)) : made ? 'draft created' : "Gmail node is off: activate 'Create Gmail draft (never sends)' and connect Gmail" } };
